// Tells whether the error when spawning a thread is temporary.
#[inline]
fn is_temporary_os_thread_error(error: &std::io::Error) -> bool {
    matches!(error.kind(), std::io::ErrorKind::WouldBlock)
}

impl Inner {
    pub(crate) fn enqueue_task(&self, shared: &mut Shared, task: Task) {
        shared.queue.push_back(task);
        self.metrics.inc_queue_depth();
    }

    pub(crate) fn wake_idle_thread(&self, shared: &mut Shared) {
        // Notify an idle worker thread. The notification counter
        // is used to count the needed amount of notifications
        // exactly. Thread libraries may generate spurious
        // wakeups, this counter is used to keep us in a
        // consistent state.
        self.metrics.dec_num_idle_threads();
        shared.num_notify += 1;
        self.condvar.notify_one();
    }

    pub(crate) fn spawn_additional_thread(
        &self,
        shared: &mut Shared,
        shutdown_tx: shutdown::Sender,
        rt: &Handle,
    ) -> Result<(), SpawnError> {
        let id = shared.worker_thread_index;

        match self.spawn_thread(shutdown_tx, rt, id) {
            Ok(handle) => {
                self.metrics.inc_num_threads();
                shared.worker_thread_index += 1;
                shared.worker_threads.insert(id, handle);
                Ok(())
            }
            Err(ref e)
                if is_temporary_os_thread_error(e)
                    && self.metrics.num_threads() > 0 =>
            {
                // OS temporarily failed to spawn a new thread.
                // The task will be picked up eventually by a currently
                // busy thread.
                Ok(())
            }
            Err(e) => {
                // The OS refused to spawn the thread and there is no thread
                // to pick up the task that has just been pushed to the queue.
                Err(SpawnError::NoThreads(e))
            }
        }
    }

    fn spawn_thread(
        &self,
        shutdown_tx: shutdown::Sender,
        rt: &Handle,
        id: usize,
    ) -> std::io::Result<thread::JoinHandle<()>> {
        let mut builder = thread::Builder::new().name((self.thread_name)());

        if let Some(stack_size) = self.stack_size {
            builder = builder.stack_size(stack_size);
        }

        let rt = rt.clone();

        builder.spawn(move || {
            // Only the reference should be moved into the closure
            let _enter = rt.enter();
            rt.inner.blocking_spawner().inner.run(id);
            drop(shutdown_tx);
        })
    }

    fn run(&self, worker_thread_id: usize) {
        if let Some(f) = &self.after_start {
            f();
        }

        let mut shared = self.shared.lock();
        let mut join_on_thread = None;

        'main: loop {
            // BUSY
            while let Some(task) = shared.queue.pop_front() {
                self.metrics.dec_queue_depth();
                drop(shared);
                task.run();

                shared = self.shared.lock();
            }

            // IDLE
            self.metrics.inc_num_idle_threads();

            while !shared.shutdown {
                let lock_result = self.condvar.wait_timeout(shared, self.keep_alive).unwrap();

                shared = lock_result.0;
                let timeout_result = lock_result.1;

                if shared.num_notify != 0 {
                    // We have received a legitimate wakeup,
                    // acknowledge it by decrementing the counter
                    // and transition to the BUSY state.
                    shared.num_notify -= 1;
                    break;
                }

                // Even if the condvar "timed out", if the pool is entering the
                // shutdown phase, we want to perform the cleanup logic.
                if !shared.shutdown && timeout_result.timed_out() {
                    // We'll join the prior timed-out thread's JoinHandle after dropping the lock.
                    // This isn't done when shutting down, because the thread calling shutdown will
                    // handle joining everything.
                    let my_handle = shared.worker_threads.remove(&worker_thread_id);
                    join_on_thread = std::mem::replace(&mut shared.last_exiting_thread, my_handle);

                    break 'main;
                }

                // Spurious wakeup detected, go back to sleep.
            }

            if shared.shutdown {
                // Drain the queue
                while let Some(task) = shared.queue.pop_front() {
                    self.metrics.dec_queue_depth();
                    drop(shared);

                    task.shutdown_or_run_if_mandatory();

                    shared = self.shared.lock();
                }

                // Work was produced, and we "took" it (by decrementing num_notify).
                // This means that num_idle was decremented once for our wakeup.
                // But, since we are exiting, we need to "undo" that, as we'll stay idle.
                self.metrics.inc_num_idle_threads();
                // NOTE: Technically we should also do num_notify++ and notify again,
                // but since we're shutting down anyway, that won't be necessary.
                break;
            }
        }

        // Thread exit
        self.metrics.dec_num_threads();

        // num_idle should now be tracked exactly, panic
        // with a descriptive message if it is not the
        // case.
        let prev_idle = self.metrics.dec_num_idle_threads();
        assert!(
            prev_idle >= self.metrics.num_idle_threads(),
            "num_idle_threads underflowed on thread exit"
        );

        if shared.shutdown && self.metrics.num_threads() == 0 {
            self.condvar.notify_one();
        }

        drop(shared);

        if let Some(f) = &self.before_stop {
            f();
        }

        if let Some(handle) = join_on_thread {
            let _ = handle.join();
        }
    }
}

